practice.solution:
-- The first task: no other task points to it
SELECT t.title AS first_task
FROM tasks AS t
WHERE NOT EXISTS (SELECT 1 FROM tasks AS x WHERE x.next_id = t.id);

-- The last task: it points nowhere
SELECT title AS last_task FROM tasks WHERE next_id IS NULL;

